package cl.bolsillo.app;
import android.content.Context;import android.graphics.*;import android.graphics.drawable.Drawable;
/** Page-level flowing ribbons; cached geometry and shaders, no per-frame allocation. */
final class PrismaBackdrop extends Drawable {
 final Paint p=new Paint(3);final Path ribbon=new Path(),fold=new Path(),seam=new Path();final boolean dark;final int primary,secondary,intensity;Shader atmosphere,ribbonTint,foldTint,edge;final RectF box=new RectF();
 PrismaBackdrop(Context c){dark=Glass.dark(c);primary=Glass.primary(c);secondary=Glass.secondary(c);intensity=Glass.intensity(c);}
 protected void onBoundsChange(Rect r){box.set(r);float x=r.left,y=r.top,w=Math.max(1,r.width()),h=Math.max(1,r.height());atmosphere=new LinearGradient(x,y,x+w,y+h,new int[]{Glass.mix(dark?0xff0d1124:0xffe7edfa,secondary,dark?.14f:.13f),dark?0xff111b2b:0xffedf6f8,Glass.mix(dark?0xff111827:0xffeff0fa,primary,dark?.08f:.07f)},new float[]{0,.55f,1},Shader.TileMode.CLAMP);ribbon.reset();ribbon.moveTo(x-w*.32f,y-h*.1f);ribbon.cubicTo(x+w*.18f,y+h*.05f,x+w*1.06f,y+h*.05f,x+w*.75f,y+h*.32f);ribbon.cubicTo(x+w*.43f,y+h*.6f,x-w*.27f,y+h*.51f,x+w*.15f,y+h*.82f);ribbon.lineTo(x+w*.5f,y+h*1.18f);ribbon.cubicTo(x-w*.22f,y+h*.84f,x-w*.39f,y+h*.66f,x+w*.24f,y+h*.37f);ribbon.cubicTo(x+w*.79f,y+h*.11f,x+w*.2f,y+h*.11f,x-w*.32f,y+h*.17f);ribbon.close();fold.reset();fold.moveTo(x+w*1.16f,y+h*.41f);fold.cubicTo(x+w*.46f,y+h*.45f,x+w*.67f,y+h*.75f,x+w*.08f,y+h*1.02f);fold.lineTo(x+w*.64f,y+h*1.13f);fold.cubicTo(x+w*1.14f,y+h*.9f,x+w*.62f,y+h*.77f,x+w*1.18f,y+h*.64f);fold.close();seam.reset();seam.moveTo(x-w*.2f,y+h*.13f);seam.cubicTo(x+w*.9f,y-h*.03f,x+w*1.06f,y+h*.13f,x+w*.54f,y+h*.36f);seam.cubicTo(x-w*.04f,y+h*.62f,x-w*.06f,y+h*.72f,x+w*.31f,y+h*.99f);ribbonTint=new LinearGradient(x,y,x+w,y+h*.77f,new int[]{Glass.alpha(secondary,dark?75:90),Glass.alpha(primary,dark?65:70),Glass.alpha(secondary,dark?20:40)},new float[]{0,.56f,1},Shader.TileMode.CLAMP);foldTint=new LinearGradient(x+w,y+h*.5f,x+w*.2f,y+h,new int[]{Glass.alpha(primary,dark?12:20),Glass.alpha(primary,dark?42:48),Glass.alpha(secondary,0)},new float[]{0,.5f,1},Shader.TileMode.CLAMP);edge=new LinearGradient(x,y,x+w,y+h,new int[]{Glass.alpha(primary,dark?68:105),0x00ffffff,Glass.alpha(secondary,dark?44:70)},new float[]{0,.57f,1},Shader.TileMode.CLAMP);}
 public void draw(Canvas c){p.setAlpha(255);p.setStyle(Paint.Style.FILL);p.setShader(atmosphere);c.drawRect(box,p);if(intensity>0){p.setShader(ribbonTint);c.drawPath(ribbon,p);p.setShader(foldTint);c.drawPath(fold,p);p.setShader(edge);p.setStyle(Paint.Style.STROKE);p.setStrokeCap(Paint.Cap.ROUND);float unit=box.width()/420f;
  // A feathered reflection follows the page ribbon, rather than outlining every card.
  int[] widths={30,19,11,5};for(int width:widths){p.setAlpha(dark?30:42);p.setStrokeWidth(width*unit);c.drawPath(seam,p);}p.setAlpha(255);p.setStrokeWidth((intensity==2?2.4f:1.4f)*unit);c.drawPath(seam,p);
 }p.setShader(null);p.setStyle(Paint.Style.FILL);p.setAlpha(255);}
 public void setAlpha(int a){}public void setColorFilter(ColorFilter f){}public int getOpacity(){return PixelFormat.OPAQUE;}
}
